INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 105211, 0.5, 0, 309, "舞踏会が開けそうな会場ね。\n素敵だわ。", 0, 0, 11, 309007);
