INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 102611, 0.5, 0, 309, "人が多くて疲れたよ～\nリマ～、おんぶしてよ～", 0, 0, 11, 309013);
