INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 103231, 0.5, 0, 310, "こうして大勢のみなさまと過ごすお正月\n賑やかで最高ですわね！", 0, 0, 11, 310001);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 103231, "", "", 310, "nop_talk_joy1", "", 0.2, 3, 310002);
