INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 104811, 0.5, 0, 310, "え？　ユカリさん？\nもう酔っぱらっちゃってる……", 0, 0, 11, 310018);
