INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 102711, 0.5, 0, 311, "この広い会場のどこかに\nあのおかたの存在を感じますわ……", 0, 0, 11, 311002);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", "", 311002, "", "", 311, "", "", "", 91, 311003);
