INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("nop_11_anna_huhuStand_loop", 0, 100911, "", 1, 311, "nop_11_anna_huhuStand_in", 0, 0.2, 3, 311005);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 100911, 0.5, 0, 311, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！", 0, 0, 11, 311006);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", "", 311006, "", "", 311, "", "", "", 91, 311007);
