INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 105011, "", "", 312, "nop_talk_tsun_pain", "", 0.2, 3, 312012);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", "", 312009, "", "", 312, "", "", "", 91, 312013);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 105011, "", 1, 312, "nop_idle_sad", "", 0.2, 3, 312014);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 105331, 0.5, 0, 313, "立派な新年会ではないか。\n我々もこの場に相応しく\n振る舞わなければな！", 0, 0, 11, 313001);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("nop_13_monica_talk_doya_loop", 0, 105331, "", 1, 313, "nop_13_monica_talk_doya", 0.2, 0.2, 3, 313002);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", "", 313001, "", "", 313, "", "", "", 91, 313003);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 105331, "", 1, 313, "nop_idle_doya", "", 0.2, 3, 313004);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 103031, 0.5, 0, 313, "おせちといえばトーゴクデース！\nオーエド町のみなさんにも\n新年のゴアイサツしないとデスね！", 0, 0, 11, 313005);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 103031, "", "", 313, "nop_talk_joy1", "", 0.2, 3, 313006);
