INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES ("", 1, 103031, "", 1, 313, "nop_idle_joy1", "", 0.2, 3, 313008);
INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (0, 8, 100811, 0.5, 0, 313, "新年会でもボクは美しいね。\nああ、会場中の視線が\n集まってるようだよ。", 0, 0, 11, 313009);
