INSERT INTO `v1_c09615dfd82984ca46b3e586dce641ba6d6ce933115fbe4eb86cc92f07cfded1` VALUES (1, 8, 105111, 0.5, 0, 511, "ふふっ、今日はお招きありがとう。\n年末は大変だったみたいね。", 0, 0, 11, 511024);
